/** Bump when pre-encoded stills are replaced. /assets and /blog are cached for a year. */
export const STILL_VERSION = "11";

export function still(src: string) {
  return src.includes("?") ? src : `${src}?v=${STILL_VERSION}`;
}

/** Responsive variants generated by scripts/optimize-content-images.mjs. */
export function imageVariant(src: string, width: number, format: "webp" | "avif") {
  return still(src.replace(/\.webp$/, `-${width}.${format}`));
}

export function imageSrcSet(src: string, widths: readonly number[], format: "webp" | "avif" = "webp") {
  return widths.map((width) => `${imageVariant(src, width, format)} ${width}w`).join(", ");
}

export const BLOG_IMAGE_WIDTHS = [640, 960] as const;
